import { useEffect, useState } from "react";

export type SessionStatus = "running" | "stopping" | "stopped";
export type Session = { id: string; agent: string; status: SessionStatus };

type BridgeContext = { sessions?: Session[] };

declare global {
  interface Window {
    codesense?: {
      subscribeContext?: (q: unknown, cb: (res: BridgeContext | null, err?: Error) => void) => () => void;
    };
  }
}

export function useSessions(): Session[] {
  const [sessions, setSessions] = useState<Session[]>([]);
  useEffect(() => {
    const cs = window.codesense;
    if (!cs?.subscribeContext) return;
    const unsubscribe = cs.subscribeContext({ kinds: ["session"] }, (res) => {
      setSessions(res?.sessions ?? []);
    });
    return () => unsubscribe();
  }, []);
  return sessions;
}

export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const m = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(m.matches);
    sync();
    m.addEventListener("change", sync);
    return () => m.removeEventListener("change", sync);
  }, []);
  return reduced;
}

